import Foundation

/// The compiled `jrbar_mediaremote` helper, embedded so the app bundle needs
/// no extra build step. Since macOS 15.4 `mediaremoted` only answers
/// processes carrying the private `com.apple.mediaremote.now-playing-read-access`
/// entitlement — our app can never hold it (the binary is killed at launch).
/// `/usr/bin/perl` is a platform binary that *does* hold it, so the monitor
/// spawns perl and has its DynaLoader `dl_load_file` this dylib, which calls
/// MediaRemote inside the entitled process and streams one JSON line per
/// now-playing change on stdout — the mediaremote-adapter pattern
/// (BSD-3-Clause, Jonas van den Berg), reduced to the one function we need.
///
/// stdin accepts `send <MRCommand>` lines for the transport; stdout speaks:
///   {"title":…,"artist":…,"album":…,"playing":bool,
///     "bundleIdentifier":…,"artworkData":"<base64>"}
///   null  — nothing is registered as now playing.
///
/// Rebuild (the source is the `adapterSource` constant below, also kept so
/// the shipped bytes are auditable):
///   for arch in arm64 x86_64; do
///     clang -dynamiclib -arch $arch -fobjc-arc -O2 \
///       -framework Foundation -framework AppKit \
///       -install_name @rpath/jrbar_mediaremote.dylib \
///       -o jrbar_mediaremote_$arch.dylib jrbar_mediaremote.m
///   done
///   lipo -create jrbar_mediaremote_{arm64,x86_64}.dylib -o jrbar_mediaremote.dylib
///
/// `dylibSHA256` pins the bytes the app writes to a temp directory; a new
/// build means a new hash, so upgrades never run a stale copy.
enum AlcoveMediaAdapterAsset {
    /// sha256 of `dylibBase64`'s decoded bytes — also the temp-file name,
    /// so a new build lands beside the old one instead of overwriting a
    /// mapped image.
    static let dylibSHA256 = "587def5ef926e1e817a8c8fe25dfa53588f3e6ed6d20cadf26584e6f50c0b072"
    static let dylibBase64 = ""

    /// The ObjC source the bytes above were built from — kept in-tree so a
    /// bump is a paste-and-recompile, never a rewrite. Build it with the
    /// clang/lipo commands in the header comment.
    static let adapterSource = #"""
// JR-Bar's MediaRemote adapter — the minimal slice of the
// mediaremote-adapter pattern (BSD-3-Clause, Jonas van den Berg).
// Since macOS 15.4 mediaremoted only answers processes carrying the
// private now-playing-read-access entitlement. /usr/bin/perl is a
// platform binary that has it, so this dylib is dlopen'd into perl by
// DynaLoader and streams now-playing JSON lines on stdout.
//
// Protocol (one JSON object per line on stdout):
//   {"title":"…","artist":"…","album":"…","playing":true,
//    "bundleIdentifier":"com.apple.Music","artworkData":"<base64>"}
//   null  — nothing is registered as now playing.
// Only meaningful changes are printed (title/artist/album/playing/
// bundle/artwork identity), plus a "ready" line on start.
#import <dlfcn.h>
#import <unistd.h>
#import <Foundation/Foundation.h>
#import <AppKit/AppKit.h>

typedef void (*MRGetInfo)(dispatch_queue_t, void (^)(NSDictionary *));
typedef void (*MRGetPlaying)(dispatch_queue_t, void (^)(BOOL));
typedef void (*MRGetPID)(dispatch_queue_t, void (^)(int));
typedef void (*MRRegister)(dispatch_queue_t);
typedef BOOL (*MRSend)(int, id);
typedef BOOL (*MRSetElapsed)(double);

static MRGetInfo mr_getInfo;
static MRGetPlaying mr_getPlaying;
static MRGetPID mr_getPID;
static MRSend mr_send;
static MRSetElapsed mr_setElapsed;
static dispatch_queue_t mr_queue;
static NSString *lastSignature;
static int lastPID;

static void emit(NSDictionary *payload) {
    NSData *json;
    if (payload == nil) {
        json = [@"null" dataUsingEncoding:NSUTF8StringEncoding];
    } else {
        NSError *error = nil;
        json = [NSJSONSerialization dataWithJSONObject:payload options:0 error:&error];
        if (json == nil) {
            fprintf(stderr, "jrbar-mediaremote: json: %s\n",
                    error.localizedDescription.UTF8String);
            return;
        }
    }
    fwrite(json.bytes, 1, json.length, stdout);
    fputc('\n', stdout);
    fflush(stdout);
}

static void refresh(void) {
    if (mr_getInfo == NULL) { emit(nil); return; }
    mr_getPlaying(mr_queue, ^(BOOL playing) {
        mr_getInfo(mr_queue, ^(NSDictionary *info) {
            NSMutableDictionary *payload = [NSMutableDictionary dictionary];
            NSString *title = [info[@"kMRMediaRemoteNowPlayingInfoTitle"] isKindOfClass:[NSString class]]
                ? info[@"kMRMediaRemoteNowPlayingInfoTitle"] : nil;
            if (title.length == 0) { emit(nil); lastSignature = @"<none>"; return; }
            payload[@"title"] = title;
            for (NSString *pair in @[@"kMRMediaRemoteNowPlayingInfoArtist:artist",
                                     @"kMRMediaRemoteNowPlayingInfoAlbum:album"]) {
                NSArray *parts = [pair componentsSeparatedByString:@":"];
                id v = info[parts[0]];
                if ([v isKindOfClass:[NSString class]] && [v length] > 0) {
                    payload[parts[1]] = v;
                }
            }
            payload[@"playing"] = @(playing);
            // Playhead + length for the scrubber. elapsed moves every
            // second so it stays out of the signature — the client
            // extrapolates it from timestamp while `playing` holds.
            id elapsed = info[@"kMRMediaRemoteNowPlayingInfoElapsedTime"];
            if ([elapsed isKindOfClass:[NSNumber class]]) {
                payload[@"elapsed"] = elapsed;
            }
            id duration = info[@"kMRMediaRemoteNowPlayingInfoDuration"];
            if ([duration isKindOfClass:[NSNumber class]] && [duration doubleValue] > 0) {
                payload[@"duration"] = duration;
            }
            id timestamp = info[@"kMRMediaRemoteNowPlayingInfoTimestamp"];
            if ([timestamp isKindOfClass:[NSDate class]]) {
                payload[@"timestamp"] = @([timestamp timeIntervalSinceReferenceDate]);
            }
            id art = info[@"kMRMediaRemoteNowPlayingInfoArtworkData"];
            if ([art isKindOfClass:[NSData class]] && [art length] > 0) {
                payload[@"artworkData"] = [art base64EncodedStringWithOptions:0];
            }
            mr_getPID(mr_queue, ^(int pid) {
                lastPID = pid;
                if (pid > 0) {
                    NSRunningApplication *app =
                        [NSRunningApplication runningApplicationWithProcessIdentifier:pid];
                    if (app.bundleIdentifier.length > 0) {
                        payload[@"bundleIdentifier"] = app.bundleIdentifier;
                    }
                }
                NSMutableString *sig = [NSMutableString stringWithFormat:@"%@|%@|%@|%@|%@|%lu|%@|%@",
                    payload[@"title"], payload[@"artist"], payload[@"album"],
                    payload[@"playing"], payload[@"bundleIdentifier"],
                    (unsigned long)[payload[@"artworkData"] length],
                    payload[@"duration"], payload[@"timestamp"]];
                if (![sig isEqualToString:lastSignature]) {
                    lastSignature = sig;
                    emit(payload);
                }
            });
        });
    });
}

static void scheduleRefresh(void) {
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 200 * NSEC_PER_MSEC),
                   mr_queue, ^{ refresh(); });
}

__attribute__((visibility("default")))
void jrbar_mr_stream(void) {
    @autoreleasepool {
        void *handle = dlopen("/System/Library/PrivateFrameworks/MediaRemote.framework/MediaRemote",
                              RTLD_LAZY);
        if (handle == NULL) {
            emit(nil);
            return;
        }
        mr_getInfo = (MRGetInfo)dlsym(handle, "MRMediaRemoteGetNowPlayingInfo");
        mr_getPlaying = (MRGetPlaying)dlsym(handle, "MRMediaRemoteGetNowPlayingApplicationIsPlaying");
        mr_getPID = (MRGetPID)dlsym(handle, "MRMediaRemoteGetNowPlayingApplicationPID");
        mr_send = (MRSend)dlsym(handle, "MRMediaRemoteSendCommand");
        mr_setElapsed = (MRSetElapsed)dlsym(handle, "MRMediaRemoteSetElapsedTime");
        MRRegister mr_register = (MRRegister)dlsym(handle, "MRMediaRemoteRegisterForNowPlayingNotifications");
        if (mr_getInfo == NULL) { emit(nil); return; }

        mr_queue = dispatch_queue_create("jrbar.mediaremote", DISPATCH_QUEUE_SERIAL);
        if (mr_register != NULL) { mr_register(mr_queue); }

        NSNotificationCenter *center = [NSNotificationCenter defaultCenter];
        for (NSString *name in @[@"kMRMediaRemoteNowPlayingInfoDidChangeNotification",
                                 @"kMRMediaRemoteNowPlayingApplicationIsPlayingDidChangeNotification",
                                 @"kMRMediaRemoteNowPlayingApplicationDidChangeNotification"]) {
            [center addObserverForName:name object:nil queue:nil
                            usingBlock:^(NSNotification *n) { scheduleRefresh(); }];
        }
        // Music's own distributed note covers players that never ping
        // MediaRemote's did-changes.
        [[NSDistributedNotificationCenter defaultCenter]
            addObserverForName:@"com.apple.Music.playerInfo" object:nil queue:nil
                    usingBlock:^(NSNotification *n) { scheduleRefresh(); }];

        // stdin: "send <MRCommand int>" for the transport,
        // "seek <seconds>" for the scrubber — both fire a refresh so
        // the next line already carries the new playhead.
        dispatch_source_t input = dispatch_source_create(
            DISPATCH_SOURCE_TYPE_READ, (uintptr_t)STDIN_FILENO, 0, mr_queue);
        dispatch_source_set_event_handler(input, ^{
            char line[64];
            ssize_t n = read(STDIN_FILENO, line, sizeof(line) - 1);
            if (n <= 0) {
                dispatch_source_cancel(input);
                CFRunLoopStop(CFRunLoopGetCurrent());
                return;
            }
            line[n] = '\0';
            if (strncmp(line, "send ", 5) == 0 && mr_send != NULL) {
                mr_send(atoi(line + 5), nil);
                scheduleRefresh();
            } else if (strncmp(line, "seek ", 5) == 0 && mr_setElapsed != NULL) {
                mr_setElapsed(atof(line + 5));
                scheduleRefresh();
            }
        });
        dispatch_resume(input);

        // A slow poll catches players that never post a did-change.
        [NSTimer scheduledTimerWithTimeInterval:5.0 repeats:YES
                                          block:^(NSTimer *t) { refresh(); }];

        emit(nil);          // "ready": the stream is live even when silent
        refresh();
        CFRunLoopRun();
    }
}
"""#
}
